// Normalize the incoming prior-authorization request and run a MOCK insurance eligibility check.
// All data here is fictional. Replace the mock with a real payer eligibility API in production.
const body = $input.first().json.body || $input.first().json;

const plans = {
  "GOLD-100": { payer: "Demo Health Plan", active: true, requiresPriorAuth: ["MRI","CT","Knee Replacement","Specialty Drug"] },
  "SILVER-200": { payer: "Demo Health Plan", active: true, requiresPriorAuth: ["MRI","Knee Replacement"] },
  "LAPSED-000": { payer: "Demo Health Plan", active: false, requiresPriorAuth: [] }
};

const plan = plans[body.plan_id] || { payer: "Unknown", active: false, requiresPriorAuth: [] };

return [{
  json: {
    request_id: body.request_id || ("PA-" + Date.now()),
    patient_name: body.patient_name || "Unknown",
    patient_age: body.patient_age || null,
    plan_id: body.plan_id || "UNKNOWN",
    procedure: body.procedure || "Unknown",
    diagnosis: body.diagnosis || "Not provided",
    clinical_notes: body.clinical_notes || "None provided",
    prior_treatments: body.prior_treatments || "None documented",
    provider_name: body.provider_name || "Unknown provider",
    payer: plan.payer,
    coverage_active: plan.active,
    prior_auth_required: plan.requiresPriorAuth.includes(body.procedure)
  }
}];

